function selectGraphAlgo(props) {
  const {negativeWeights,kHopLimit,incrementalConnectivity,mst,topoSort,eulerianPath,nonNegSingleSource}=props;
  if(eulerianPath)return"Hierholzer's O(E log E)";
  if(topoSort)return'Topological Sort O(V+E)';
  if(mst)return'Kruskal O(E log E)';
  if(incrementalConnectivity)return'Union-Find O(alpha(n))';
  if(negativeWeights||kHopLimit)return'Bellman-Ford O(V*E)';
  return'Dijkstra O((V+E)logV)';
}

function graphSprintStats(sprints) {
  const byCategory={};
  let total=0;
  sprints.forEach((sprint,i)=>{byCategory[i]=sprint.length;total+=sprint.length;});
  return{total,byCategory};
}

