function totalTargetTime(problems) {
  return problems.reduce((sum,p)=>sum+(p.target||0),0);
}

function hardestProblem(problems) {
  if(!problems.length)return null;
  return problems.reduce((max,p)=>p.target>max.target?p:max);
}

