solution.code:
function verifyProblemLog(log) {
  const allAt5=log.every(p=>p.score===5);
  const totalSolves=log.reduce((s,p)=>s+p.solveCount,0);
  const problemsMissing2Solves=log.filter(p=>p.solveCount<2).length;
  return{allAt5,totalSolves,problemsMissing2Solves};
}

function level2Certified(log, consecutiveSessions) {
  const {allAt5,problemsMissing2Solves}=verifyProblemLog(log);
  return allAt5&&problemsMissing2Solves===0&&consecutiveSessions>=2;
}

function categoryTotal(categoryCount) {
  return Object.values(categoryCount).reduce((s,n)=>s+n,0);
}
